def request(endpoint, body, token, transport, clock):
    if not token:
        raise ValueError('token required')
    response = transport.post(endpoint, json=body, headers={'Authorization': 'Bearer ' + token}, timeout=5)
    if response.status == 429:
        clock.sleep(min(30, max(0, int(response.headers.get('Retry-After', '1')))))
        return {'kind': 'retry_later'}
    if response.status == 404:
        return None
    if response.status >= 400:
        raise RuntimeError(response.status)
    if response.status == 204:
        return {}
    return response.json()

